import{_ as a,o as s,c as i,a2 as o}from"./chunks/framework.Dxeykp0S.js";const u=JSON.parse('{"title":"Day 6 · 把 Python 服务部署上 K8s","description":"","frontmatter":{},"headers":[],"relativePath":"pro/06-k8s-deploy.md","filePath":"pro/06-k8s-deploy.md","lastUpdated":1787141678000}'),l={name:"pro/06-k8s-deploy.md"};function r(t,e,n,d,c,h){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="day-6-·-把-python-服务部署上-k8s" tabindex="-1">Day 6 · 把 Python 服务部署上 K8s <a class="header-anchor" href="#day-6-·-把-python-服务部署上-k8s" aria-label="Permalink to &quot;Day 6 · 把 Python 服务部署上 K8s&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>K8s 对应用是语言无关的。本课会先完成 Deployment、Service、Ingress 与 HPA 的基本配置，再重点分析 Python 应用的资源画像（GIL 影响 CPU 限额策略）、ASGI 服务器的 worker 配置与 K8s 副本数的权衡。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>为 FastAPI 应用编写完整 K8s 清单</li><li>配置就绪/存活探针（readiness/liveness）</li><li>理解 Python 应用的 requests/limits 配置策略</li><li>体验 HPA 自动扩缩容</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://kubernetes.io/zh-cn/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/" target="_blank" rel="noreferrer">Kubernetes 官方：配置 Liveness/Readiness 探针</a></li><li><a href="https://www.uvicorn.org/deployment/" target="_blank" rel="noreferrer">uvicorn 部署文档（含容器场景）</a></li><li>关键认知：因为 GIL，一个 Python 进程基本只能吃满一个核。K8s 里的 Python 应用伸缩策略 = <strong>单进程单核，多副本水平扩展</strong>，而不是像 Java 那样给单 Pod 配多核。</li></ul><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>本地集群</strong>：用 <code>kind</code> 或 <code>k3d</code> 启动本地 K8s 集群，把 Day 5 的镜像 load 进去（<code>kind load docker-image</code>）。</p></li><li><p><strong>编写清单</strong>：</p></li></ol><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># deployment.yaml 关键要素</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># - replicas: 2</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># - resources: requests cpu 250m / memory 256Mi, limits cpu 1 / memory 512Mi</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># - readinessProbe 与 livenessProbe 指向 /healthz（需先在 FastAPI 里实现）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># - envFrom configMap/secret</span></span></code></pre></div><p>在 FastAPI 应用中实现 <code>/healthz</code>（存活：进程活着就返回 200）和 <code>/readyz</code>（就绪：检查 DB/Redis 连接）两个端点，理解两者的语义差异：liveness 失败重启 Pod，readiness 失败摘流量。</p><ol start="3"><li><p><strong>配置管理</strong>：把应用配置（数据库地址、日志级别）拆到 ConfigMap，密钥（API key）放 Secret，用 <code>envFrom</code> 注入。修改 ConfigMap 后滚动更新，观察 Pod 重建。</p></li><li><p><strong>扩缩容实验</strong>：</p><ul><li>配置 HPA（CPU 利用率 70% 触发，1-5 副本）</li><li>用 <code>kubectl run</code> 起压测 Pod 或直接用 k6（老本行）打流量</li><li>观察 <code>kubectl get hpa -w</code> 的扩容过程</li></ul></li><li><p><strong>优雅下线</strong>：给应用加 SIGTERM 处理（uvicorn 默认支持优雅关闭），配置 <code>terminationGracePeriodSeconds</code> 和 preStop 钩子，滚动更新时确保零请求中断。用持续打流量 + <code>kubectl rollout restart</code> 验证。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>为什么 Python 服务的 CPU limit 不宜设成多核单副本？（联系 GIL）</li><li>readiness 和 liveness 探针用同一个端点有什么风险？</li><li>uvicorn 的 <code>--workers 4</code> 和 K8s <code>replicas: 4</code> 分别是什么粒度？容器场景推荐哪种？</li><li>HPA 基于 CPU 伸缩对 IO 密集型 Python 服务有效吗？有什么替代指标？</li><li>滚动更新期间，Pod 被摘出 Service endpoints 的时机与 SIGTERM 的先后顺序？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://kubernetes.io/zh-cn/docs/concepts/workloads/pods/pod-lifecycle/" target="_blank" rel="noreferrer">K8s 官方：Pod 生命周期与终止</a></li><li><a href="https://keda.sh/" target="_blank" rel="noreferrer">KEDA</a> —— 事件驱动的自动伸缩（如按队列长度伸缩 AI 任务消费者）</li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节是<a href="./07-final-project">毕业设计</a>：把预备班到高级班的所有知识，融进一个完整上线的服务。</p>`,20)])])}const k=a(l,[["render",r]]);export{u as __pageData,k as default};
